package io.beep.core.app.enterprise;
import io.beep.core.app.port.*;
import io.beep.core.app.auth.*;
import io.beep.core.app.workspace.Workspaces;
import io.beep.core.app.common.PublicSite;
import io.beep.core.domain.DomainException;
import io.beep.core.domain.enterprise.EnterprisePolicy;
import io.beep.core.domain.user.*;
import java.time.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.*;
import static io.beep.core.domain.enterprise.EnterprisePolicy.*;
public class EnterpriseUseCase {
 private final EnterpriseRepository data;private final EcosystemRepository teams;private final Workspaces rights;private final WorkspaceRepository ws;private final UserRepository users;private final TrustRepository audit;private final EnterpriseSsoPort sso;private final TokenPort tokens;private final SecretCipherPort cipher;private final TransactionPort tx;private final SessionIssuer sessions;private final Clock clock;private final PublicSite site;
 public EnterpriseUseCase(EnterpriseRepository data,EcosystemRepository teams,Workspaces rights,WorkspaceRepository ws,UserRepository users,TrustRepository audit,EnterpriseSsoPort sso,TokenPort tokens,SecretCipherPort cipher,TransactionPort tx,SessionIssuer sessions,Clock clock,PublicSite site){this.data=data;this.teams=teams;this.rights=rights;this.ws=ws;this.users=users;this.audit=audit;this.sso=sso;this.tokens=tokens;this.cipher=cipher;this.tx=tx;this.sessions=sessions;this.clock=clock;this.site=site;}
 public Map<String,Object> overview(){return data.overview(clock.instant());}
 public Map<String,Object> workspace(UUID w){if(ws.findById(w).isEmpty())throw new DomainException("not_found");return Map.of("contract",data.contract(w).orElse(Map.of()),"apps",data.apps(w));}
 private Map<String,Object> active(UUID w){var c=data.contract(w).orElseThrow(()->new DomainException("feature_unavailable"));if(!EnterprisePolicy.active(c,clock.instant()))throw new DomainException("feature_unavailable");var workspace=ws.findById(w).orElseThrow(()->new DomainException("not_found"));workspace.requireWritable();return c;}
 public Map<String,Object> settings(User u){UUID w=rights.ensureFor(u).id();return Map.of("workspaceId",w,"contract",data.contract(w).orElse(Map.of()),"apps",data.apps(w),"manages",teams.role(w,u.id()).map(r->r.manages()).orElse(false));}
 public void checkAccess(UUID w,String ip,String session,boolean api){var found=data.contract(w);if(found.isEmpty())return;var c=found.get();allowed(c,ip);var config=config(c);if(!api&&Boolean.TRUE.equals(config.get("required"))&&!data.hasProof(session==null?null:tokens.hash(session),w,((Number)c.get("version")).intValue()))throw new DomainException("sso_required");}
 @SuppressWarnings("unchecked") private static Map<String,Object> config(Map<String,Object> c){return c.get("sso") instanceof Map<?,?> m?(Map<String,Object>)m:Map.of();}
 public Map<String,Object> save(UUID w,Map<String,Object> b,UUID staff){String why=text(b,"reason",3,1000);var c=contract(b);Map<String,Object> config=new LinkedHashMap<>();if(b.get("sso") instanceof Map<?,?> raw&&!raw.isEmpty()){for(String key:List.of("issuer","clientId","authorizationUrl","tokenUrl","jwksUrl")){Object value=raw.get(key);if(!(value instanceof String v)||v.isBlank()||v.length()>2048)throw new DomainException("invalid_request");config.put(key,v);}config.put("required",Boolean.TRUE.equals(raw.get("required")));sso.validate(config);}
  String secret=Objects.toString(b.get("ssoSecret"),"");if(secret.length()>4096)throw new DomainException("invalid_request");String encrypted=secret.isEmpty()?"":cipher.encrypt(secret);
  return tx.run(()->{String saved=encrypted;if(!b.containsKey("ssoSecret")&&!config.isEmpty()){var previous=data.contract(w);if(previous.isPresent()&&config(previous.get()).equals(config))saved=data.ssoSecret(w);}data.saveContract(w,c,config,saved,staff,clock.instant());audit.audit(staff.toString(),"enterprise.contract",w.toString(),why);return workspace(w);});
 }
 public Map<String,Object> evidence(Map<String,Object>b,UUID staff){String why=text(b,"reason",3,1000);String framework=text(b,"framework",1,30);if(!Set.of("soc2","iso27001","security_audit","pentest").contains(framework))throw new DomainException("invalid_request");text(b,"control",3,200);https(text(b,"url",1,2048));hash(b);if(!instant(b,"expiresAt").isAfter(clock.instant()))throw new DomainException("invalid_request");tx.run(()->{data.evidence(b,staff,clock.instant());audit.audit(staff.toString(),"compliance.evidence",framework,why);});return Map.of("saved",true);}
 private static void hash(Map<String,Object>b){if(!text(b,"sha256",64,64).matches("[a-f0-9]{64}"))throw new DomainException("invalid_request");}
 public Map<String,Object> sdk(Map<String,Object>b,UUID staff){String why=text(b,"reason",3,1000);if(!Set.of("android","ios","typescript").contains(text(b,"platform",1,20))||!Set.of("active","deprecated","revoked").contains(text(b,"status",1,20)))throw new DomainException("invalid_request");for(String k:List.of("version","minimumVersion"))if(!text(b,k,5,40).matches("[0-9]+\\.[0-9]+\\.[0-9]+(?:-[A-Za-z0-9.-]+)?"))throw new DomainException("invalid_request");https(text(b,"url",1,2048));hash(b);tx.run(()->{data.sdk(b,staff,clock.instant());audit.audit(staff.toString(),"sdk.release",b.get("platform")+"/"+b.get("version"),why);});return Map.of("saved",true);}
 public Map<String,Object> review(Map<String,Object>b,UUID staff){String why=text(b,"reason",3,1000),decision=text(b,"decision",1,30);if(!Set.of("approved","remediation_required").contains(decision))throw new DomainException("invalid_request");UUID w=uuid(b.get("workspaceId"));tx.run(()->{data.review(w,decision,why,staff,clock.instant());audit.audit(staff.toString(),"compliance.access_review",w.toString(),why);});return Map.of("saved",true);}
 public Map<String,Object> failover(Map<String,Object>b,UUID staff){String why=text(b,"reason",3,1000),action=text(b,"action",1,20);if(!Set.of("request","confirm","cancel").contains(action))throw new DomainException("invalid_request");String node=action.equals("request")?text(b,"nodeId",1,128):"";UUID id=action.equals("request")?null:uuid(b.get("id"));return tx.run(()->{var result=data.failover(node,id,action,why,staff,clock.instant());audit.audit(staff.toString(),"operations.failover."+action,action.equals("request")?node:id.toString(),why);return result;});}
 private UUID manage(User u){UUID w=rights.ensureFor(u).id();if(!teams.role(w,u.id()).map(r->r.manages()).orElse(false))throw new DomainException("forbidden");active(w);return w;}
 public Map<String,Object> registerApp(User u,Map<String,Object>b){UUID w=manage(u),id=UUID.randomUUID();var candidate=new LinkedHashMap<String,Object>();candidate.put("id",id);candidate.put("name",text(b,"name",1,80));String scheme=text(b,"scheme",2,40);if(!scheme.matches("[a-z][a-z0-9+.-]{1,39}")||Set.of("http","https","javascript","file","data","intent").contains(scheme))throw new DomainException("invalid_request");candidate.put("scheme",scheme);for(String key:List.of("androidStore","iosStore")){String url=text(b,key,1,2048);https(url);if(!URI.create(url).getHost().equals(key.equals("androidStore")?"play.google.com":"apps.apple.com"))throw new DomainException("invalid_request");candidate.put(key,url);}tx.run(()->{ws.lock(w);data.app(w,candidate,clock.instant());teams.audit(w,u.id(),"mobile.app.created",id.toString(),clock.instant());});return Map.of("id",id);}
 public void disableApp(User u,UUID id){UUID w=manage(u);tx.run(()->{data.disableApp(w,id);teams.audit(w,u.id(),"mobile.app.disabled",id.toString(),clock.instant());});}
 private Map<String,Object> mobile(UUID id){var app=data.app(id).orElseThrow(()->new DomainException("not_found"));if(!Boolean.TRUE.equals(app.get("enabled")))throw new DomainException("not_found");active(uuid(app.get("workspaceId")));return app;}
 public Map<String,Object> issue(UUID appId,Map<String,Object>b){var app=mobile(appId);if(!Boolean.TRUE.equals(b.get("consent")))throw new DomainException("consent_required");String platform=text(b,"platform",1,10),destination=text(b,"destination",1,2048);if(!Set.of("android","ios").contains(platform))throw new DomainException("invalid_request");try{URI u=URI.create(destination);if(!app.get("scheme").equals(u.getScheme())||u.getUserInfo()!=null)throw new IllegalArgumentException();}catch(Exception e){throw new DomainException("invalid_request");}String raw=tokens.newToken();Instant now=clock.instant(),expiry=now.plus(Duration.ofHours(24));data.deferred(tokens.hash(raw),appId,cipher.encrypt(destination),platform,now,expiry);String store=app.get(platform.equals("android")?"androidStore":"iosStore").toString();if(platform.equals("android"))store+=(store.contains("?")?"&":"?")+"referrer="+URLEncoder.encode("beep_token="+raw,StandardCharsets.UTF_8);return Map.of("token",raw,"expiresAt",expiry,"storeUrl",store,"handoff",platform.equals("android")?"install_referrer":"explicit_token");}
 public Map<String,Object> resolve(Map<String,Object>b){UUID id=uuid(b.get("appId"));mobile(id);String token=text(b,"token",32,128),platform=text(b,"platform",1,10);if(!Set.of("android","ios").contains(platform))throw new DomainException("invalid_request");return tx.run(()->Map.of("destination",cipher.decrypt(data.consumeDeferred(tokens.hash(token),id,platform,clock.instant()).orElseThrow(()->new DomainException("invalid_token")))));}
 private Map<String,Object> authenticationContract(UUID w){var c=data.contract(w).orElseThrow(()->new DomainException("not_found"));ws.findById(w).orElseThrow(()->new DomainException("not_found")).requireWritable();return c;}
 public record Start(String url,String state){}
 public Start start(UUID w,String ip){var c=authenticationContract(w);allowed(c,ip);var config=config(c);if(config.isEmpty())throw new DomainException("not_found");String state=tokens.newToken(),nonce=tokens.newToken(),verifier=tokens.newToken();String challenge;try{challenge=Base64.getUrlEncoder().withoutPadding().encodeToString(MessageDigest.getInstance("SHA-256").digest(verifier.getBytes(StandardCharsets.US_ASCII)));}catch(Exception e){throw new IllegalStateException(e);}data.state(tokens.hash(state),w,((Number)c.get("version")).intValue(),cipher.encrypt(verifier),nonce,clock.instant().plusSeconds(600));return new Start(sso.authorization(config,state,nonce,challenge,callback(w)),state);}
 public AuthOutcome complete(UUID w,String state,String browserState,String code,String ip){if(state==null||state.length()>128||browserState==null||!MessageDigest.isEqual(state.getBytes(StandardCharsets.UTF_8),browserState.getBytes(StandardCharsets.UTF_8))||code==null||code.length()>4096)throw new DomainException("sso_failed");var saved=data.consumeState(tokens.hash(state),clock.instant()).orElseThrow(()->new DomainException("sso_failed"));var c=authenticationContract(w);if(!w.equals(saved.get("workspace"))||!Objects.equals(saved.get("version"),c.get("version")))throw new DomainException("sso_failed");allowed(c,ip);var config=config(c);var identity=sso.exchange(config,cipher.decrypt(data.ssoSecret(w).isEmpty()?cipher.encrypt(""):data.ssoSecret(w)),code,cipher.decrypt(saved.get("verifier").toString()),saved.get("nonce").toString(),callback(w));
  return tx.run(()->{ws.lock(w);var current=authenticationContract(w);if(!Objects.equals(current.get("version"),c.get("version")))throw new DomainException("sso_failed");User user=data.identity(w,identity.issuer(),identity.subject()).flatMap(users::findById).orElseGet(()->{if(!identity.verified())throw new DomainException("forbidden");User candidate=users.findByEmail(new Email(identity.email())).orElseThrow(()->new DomainException("forbidden"));if(!candidate.emailVerified()||!teams.canAccess(w,candidate.id()))throw new DomainException("forbidden");data.bindIdentity(w,identity.issuer(),identity.subject(),candidate.id());return candidate;});if(!user.canLogin()||!teams.canAccess(w,user.id()))throw new DomainException("forbidden");var out=sessions.afterFirstFactor(user);int v=((Number)c.get("version")).intValue();if(out.mfaRequired())data.pendingProof(tokens.hash(out.mfaToken()),w,v,clock.instant().plusSeconds(600));else data.proof(tokens.hash(out.sessionToken()),w,v);teams.audit(w,user.id(),"sso.login",identity.issuer(),clock.instant());return out;});}
 public void completeMfa(String mfa,String session){data.completeProof(tokens.hash(mfa),tokens.hash(session),clock.instant());}
 private String callback(UUID w){return site.url()+"/v1/auth/sso/"+w+"/callback";}
 public static UUID uuid(Object value){try{return UUID.fromString(Objects.toString(value));}catch(Exception e){throw new DomainException("invalid_request");}}
}
